 const homeCertSummary={"VCA": {"en": "Associate", "focus": "바이브코딩 기본 역량 과정", "desc": "AI와 협업해 주어진 요구사항을 구현하고, 결과를 확인하며 안전하게 활용하는 기본 역량."}, "VCP": {"en": "Professional", "focus": "웹페이지 · 앱 · 프로그램 · DB · 서버", "desc": "화면부터 데이터·서버까지 연결해 실서비스를 구현하고 배포하는 실무 역량."}, "VCE": {"en": "Expert", "focus": "아키텍처 · 오케스트레이션 · 통합", "desc": "여러 도메인을 아우르는 시스템을 설계·통합하고 기술적 의사결정을 이끄는 전문 역량."}};
 if(q('bHomeTiers')) q('bHomeTiers').innerHTML=SITE.certs.filter(c=>c.code!=='CON').map(c=>{const m=homeCertSummary[c.code]||{};return '<div class="tier" data-r="'+c.route+'"><div class="nh-cert-top"><span class="g">'+esc(c.code)+' · '+esc(c.grade.split(' · ')[0])+'</span><span class="lv">'+esc(m.en||c.en)+'</span></div><h3>'+esc(c.name.replace('바이브코딩 ',''))+'</h3><div class="nh-cert-focus">'+esc(m.focus||'')+'</div><p>'+esc(m.desc||c.desc)+'</p><div class="nh-cert-hours">누적 학습 '+esc(c.hours.replace('h','시간'))+'</div></div>';}).join('');
 const nrow=(n,i)=>'<a class="brow" href="#noticeview?post='+encodeURIComponent(n.id)+'" data-nv="'+i+'"><span class="tt">'+esc(n.title)+'</span><span class="d">'+esc(n.date.slice(5))+'</span></a>';
 if(q('bHomeNotice')) q('bHomeNotice').innerHTML=SITE.notices.map((n,i)=>({n,i})).filter(o=>o.n.cat==='공지').slice(0,3).map(o=>nrow(o.n,o.i)).join('');
 if(q('bHomeRecruit')) q('bHomeRecruit').innerHTML=SITE.notices.map((n,i)=>({n,i})).filter(o=>o.n.cat==='모집').slice(0,2).map(o=>nrow(o.n,o.i)).join('');
 if(q('bHomePress')) q('bHomePress').innerHTML=SITE.press.slice(0,6).map(x=>'<a class="brow" href="#press" data-r="press"><span class="tt">'+esc(x.title)+'</span>'+(x.date?'<span class="d">'+esc(x.date.slice(5))+'</span>':'')+'</a>').join('');
 const catRow=(n,i)=>'<a class="brow" href="#noticeview?post='+encodeURIComponent(n.id)+'" data-nv="'+i+'"><span class="tt">'+esc(n.title)+'</span><span class="d">'+esc(n.date)+'</span></a>';
 const byCat=c=>SITE.notices.map((n,i)=>({n,i})).filter(o=>o.n.cat===c);
 if(q('bNoticeList')){const L=byCat('공지');
   q('bNoticeList').innerHTML=L.map(o=>catRow(o.n,o.i)).join('')||'<div class="emptyrow">등록된 공지가 없습니다.</div>';
   if(q('cntNotice'))q('cntNotice').textContent='총 '+L.length+'건';}
 if(q('bRecruitList')){const L=byCat('모집');
   q('bRecruitList').innerHTML=L.map(o=>catRow(o.n,o.i)).join('')||'<div class="emptyrow">진행 중인 모집이 없습니다.</div>';
   if(q('cntRecruit'))q('cntRecruit').textContent='총 '+L.length+'건';}
