function amShow(k){
 document.querySelectorAll('.adm-side a').forEach(a=>a.classList.toggle('on',a.dataset.am===k));
 document.querySelectorAll('.ampane').forEach(s=>s.classList.toggle('on',s.id==='am-'+k));
 document.getElementById('amTitle').textContent=AMT[k]||'';
 document.querySelector('.adm-side')?.classList.remove('is-open');
 document.getElementById('admMenuToggle')?.setAttribute('aria-expanded','false');
 window.scrollTo({top:0});
}
function chip(s){
 const m={'활성':'ok','확인':'ok','답변완료':'ok','인증':'ok','승인대기':'wait','접수':'wait','미답변':'wait',
  '심사중':'rev','준비 중':'rev','정지':'no','반려':'no','미개설':'off'};
 return '<span class="chip '+(m[s]||'off')+'">'+esc(s)+'</span>';
}
function rowBtns(idx,type){
 return '<div class="acts2"><button class="abtn sm" data-ed="'+type+'" data-i="'+idx+'">수정</button><button class="abtn sm dgr" data-del="'+type+'" data-i="'+idx+'">삭제</button></div>';
}
