 if(q('tInq')) q('tInq').innerHTML=INQS.map((x,i)=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.type)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.email)+'</td><td style="max-width:260px;color:var(--sub)">'+esc(x.msg)+'</td><td>'+chip(x.status)+'</td><td><div class="acts2"><button class="abtn sm" data-inq="ok" data-i="'+i+'">답변완료</button><button class="abtn sm dgr" data-del="inq" data-i="'+i+'">삭제</button></div></td></tr>').join('')||'<tr><td colspan="7" class="emptyrow">문의가 없습니다.</td></tr>';
