// members 테이블은 'individual' / 'active' 같은 영문 값을 쓰고, 필터·칩은 '개인' / '활성' 을 씁니다.
// 원래 코드는 이 차이를 정규화하지 않아 유형·상태 필터가 아무것도 못 잡았습니다.
const MEMBER_TYPE_LABEL={individual:'개인',company:'기업(회원사)',institute:'교육기관'};
const MEMBER_STATE_LABEL={active:'활성',pending:'승인대기',suspended:'정지'};
function memberTypeLabel(t){return MEMBER_TYPE_LABEL[t]||t||'개인';}
function memberStateLabel(s){return MEMBER_STATE_LABEL[s]||s||'승인대기';}
// '사이트 계정만' / '협회 회원만' 필터 값
function memberSrc(m){return m.isAssoc?'assoc':(m.src||'site');}
function renderMembers(){
 const tb=document.getElementById('tMember'); if(!tb) return;
 const pending=MEMBERS.map((m,i)=>({m,i})).filter(({m})=>memberStateLabel(m.status)==='승인대기');
 document.getElementById('admPending').innerHTML=pending.length?'<strong>가입 승인 대기 '+pending.length+'건</strong>'+pending.map(({m,i})=>'<div class="adm-pending-row"><span><b>'+esc(m.name)+'</b> · '+esc(memberTypeLabel(m.type))+' · '+esc(m.isAssoc?'협회 회원':'사이트 계정')+'</span><button class="abtn sm pri" type="button" data-mok="'+i+'">승인</button></div>').join(''):'';
 const kw=(document.getElementById('qMember')?.value||'').toLowerCase();
 const ty=document.getElementById('fType')?.value||''; const st=document.getElementById('fStatus')?.value||'';
 const src=document.getElementById('fSrc')?.value||'';
 const hit=s=>String(s==null?'':s).toLowerCase();
 const rows=MEMBERS.map((m,i)=>({m,i})).filter(({m})=>
   (!kw||hit(m.name).includes(kw)||hit(m.email).includes(kw)||hit(m.id).includes(kw)||hit(m.org).includes(kw))
   &&(!ty||memberTypeLabel(m.type)===ty)&&(!st||memberStateLabel(m.status)===st)
   &&(!src||memberSrc(m)===src));
 tb.innerHTML=rows.map(({m,i})=>{
  const label=m.isAssoc?'<b>협회 회원</b>':'사이트 계정';
  const sub=m.isAssoc&&m.src==='join'?' <span class="chip rev">신청만</span>':'';
  return '<tr><td class="mono" style="font-size:12px">'+esc(m.no||'-')+'</td>'
  +'<td><b>'+esc(m.name)+'</b>'+(m.org?'<div style="font-size:12px;color:var(--sub)">'+esc(m.org)+'</div>':'')+'</td>'
  +'<td>'+esc(memberTypeLabel(m.type))+'</td>'
  +'<td>'+label+sub+'</td>'
  +'<td style="font-size:12.5px">'+(m.email?esc(m.email):'<span style="color:var(--faint)">-</span>')+'<br><span style="color:var(--faint)">'+esc(m.phone||'-')+'</span></td>'
  +'<td>'+esc(m.joined)+'</td><td>'+esc(m.certs||'-')+'</td>'
  +'<td>'+chip(memberStateLabel(m.status))+'</td>'
  +'<td><div class="acts2"><button class="abtn sm" data-mv="'+i+'">상세</button>'
  +(memberStateLabel(m.status)==='승인대기'?'<button class="abtn sm pri" data-mok="'+i+'">승인</button>':'')
  +'<button class="abtn sm dgr" data-del="member" data-i="'+i+'">삭제</button></div></td></tr>';
 }).join('')
   ||'<tr><td colspan="9" class="emptyrow">조건에 맞는 회원이 없습니다.</td></tr>';
}
/* ---- 공용 에디터 ---- */
let aeSaveFn=null;
function openEditor(title,fields,vals,onSave){
 document.getElementById('aeTitle').textContent=title;
 document.getElementById('aeFields').innerHTML=fields.map(f=>{
  const v=esc(vals[f.k]==null?'':vals[f.k]);
  if(f.k==='cover')return '<div><label>표지 이미지</label><input type="hidden" data-k="cover" value="'+bookAttr(vals.cover||'')+'"><div class="adm-book-drop" id="aeBookDrop" role="button" tabindex="0" aria-label="도서 표지 사진 선택 또는 드래그 앤 드롭"><img id="aeBookPreview" src="'+bookAttr(bookCover(vals.cover||''))+'" alt="선택한 표지 미리보기"'+(bookCover(vals.cover||'')?'':' hidden')+'><span id="aeBookDropLabel">표지 사진을 선택하거나 여기에 끌어 놓으세요</span></div><input type="file" id="aeBookFile" accept="image/png,image/jpeg,image/webp" hidden><p class="adm-book-drop-note">JPG·PNG·WebP 사진을 브라우저에 저장합니다. 실제 서버 저장은 개발 연동 후 가능합니다.</p><input type="url" id="aeBookCoverUrl" placeholder="또는 https:// 표지 이미지 주소" value="'+bookAttr(/^https:\/\//.test(vals.cover||'')?vals.cover:'')+'"></div>';
  if(f.t==='textarea') return '<div><label>'+f.l+'</label><textarea data-k="'+f.k+'">'+v+'</textarea></div>';
  if(f.t==='select') return '<div><label>'+f.l+'</label><select data-k="'+f.k+'">'+f.o.map(o=>'<option'+(vals[f.k]===o?' selected':'')+'>'+o+'</option>').join('')+'</select></div>';
  return '<div><label>'+f.l+'</label><input data-k="'+f.k+'" value="'+v+'"></div>';
 }).join('');
 aeSaveFn=()=>{const o={};document.querySelectorAll('#aeFields [data-k]').forEach(el=>o[el.dataset.k]=el.value);onSave(o);};
 const zone=document.getElementById('aeBookDrop');
 if(zone){
  const fileInput=document.getElementById('aeBookFile'),coverInput=document.querySelector('#aeFields [data-k="cover"]'),urlInput=document.getElementById('aeBookCoverUrl'),preview=document.getElementById('aeBookPreview');
  const setCover=value=>{coverInput.value=value;preview.src=bookCover(value);preview.hidden=!bookCover(value);};
  const loadFile=file=>{
   if(!file)return;
   if(!/^image\/(?:png|jpeg|webp)$/.test(file.type)){alert('JPG, PNG 또는 WebP 사진을 선택해 주세요.');return;}
   const reader=new FileReader();
   reader.onload=()=>{const image=new Image();image.onload=()=>{
    const scale=Math.min(1,360/image.width,520/image.height),canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));
    const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);
    const data=canvas.toDataURL('image/jpeg',.82);
    if(data.length>=500000){alert('이미지가 너무 큽니다. 다른 사진을 선택해 주세요.');return;}
    setCover(data);urlInput.value='';document.getElementById('aeBookDropLabel').textContent=file.name+' 선택됨';
   };image.onerror=()=>alert('사진을 읽을 수 없습니다.');image.src=String(reader.result);};
   reader.onerror=()=>alert('사진을 읽을 수 없습니다.');reader.readAsDataURL(file);
  };
  zone.addEventListener('click',()=>fileInput.click());
  zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fileInput.click();}});
  zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('is-dragover');});
  zone.addEventListener('dragleave',()=>zone.classList.remove('is-dragover'));
  zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('is-dragover');loadFile(e.dataTransfer.files[0]);});
  fileInput.addEventListener('change',()=>loadFile(fileInput.files[0]));
  urlInput.addEventListener('input',()=>{setCover(urlInput.value.trim());document.getElementById('aeBookDropLabel').textContent='표지 사진을 선택하거나 여기에 끌어 놓으세요';});
 }
 document.getElementById('aEditor').hidden=false;
}
