 banner:[{k:'tag',l:'태그'},{k:'t',l:'제목'},{k:'d',l:'설명'},{k:'r',l:'연결 페이지',t:'select',o:['home','about','cert','edu','join','notice','press','member','verify']}],
 stat:[{k:'n',l:'숫자'},{k:'l',l:'설명'}],
