 cert:[{k:'code',l:'코드'},{k:'grade',l:'등급 (예: 3급 · 입문)'},{k:'name',l:'명칭'},{k:'en',l:'영문명'},{k:'hours',l:'교육시간'},{k:'method',l:'검정방법'},{k:'target',l:'대상'},{k:'desc',l:'설명',t:'textarea'},{k:'route',l:'연결 페이지'}],
 exam:[{k:'round',l:'회차'},{k:'cert',l:'종목'},{k:'apply',l:'접수기간'},{k:'date',l:'시험일'},{k:'status',l:'상태',t:'select',o:['준비 중','접수','시행','미개설']}],
 notice:[{k:'cat',l:'분류',t:'select',o:['공지','모집','보도','행사']},{k:'title',l:'제목'},{k:'date',l:'게시일 (YYYY.MM.DD)'},{k:'body',l:'본문',t:'textarea'}],
