 async function doCertVerify(cno,nm,br,outId){
 var out=document.getElementById(outId||'verifyOut');
 if(!cno){if(out)out.innerHTML='자격번호를 입력해 조회하세요.';return;}
 if(out)out.innerHTML='조회 중…';
 try{
  var fb=window.kvcfClient&&window.kvcfClient();
  if(!fb){if(out)out.innerHTML='<b>'+esc(cno)+'</b><br>ForgeDB 연결이 없어 조회할 수 없습니다.';return;}
  var r=await fb.rpc('verify_cert_number',{p_cert_no:cno,p_name:nm||'',p_birth:br||''});
  if(r.error){if(out)out.innerHTML='<b>'+esc(cno)+'</b><br>조회 실패: '+esc(r.error.message||'DB 오류');return;}
  var rows=(r.data&&r.data.length)?r.data:null;
  if(!rows){if(out)out.innerHTML='<b>'+esc(cno)+'</b><br><span class="chip no">일치하는 자격번호가 없습니다</span><br><span style="color:var(--sub);font-size:13px">성명·생년월일 정보를 함께 입력하셨으면 다시 확인해 주세요.</span>';return;}
  var row=rows[0];
  var masked=row.holder_name.length<=2?row.holder_name.charAt(0)+'*':row.holder_name.charAt(0)+'○'+row.holder_name.slice(-1);
  if(out)out.innerHTML=
   '<div class="vrow"><span class="k">자격번호</span><span class="v"><b>'+esc(row.cert_no)+'</b></span></div>'+
   '<div class="vrow"><span class="k">자격 종목</span><span class="v">'+esc(row.cert_name)+'</span></div>'+
   '<div class="vrow"><span class="k">성명</span><span class="v">'+esc(masked)+'</span></div>'+
   '<div class="vrow"><span class="k">발급일</span><span class="v">'+esc(row.issued_at)+'</span></div>'+
   '<div class="vrow"><span class="k">상태</span><span class="status"><span class="chip '+(row.state==='유효'?'ok':'no')+'">'+esc(row.state)+' / '+(row.state==='유효'?'VALID':'CHECK')+'</span></span></div>';
 }catch(err){if(out){out.innerHTML='<b>'+esc(cno)+'</b><br>조회 중 오류: '+esc((err&&err.message)||'unknown');}}
}
