function restoreRoute(){
 const raw=(location.hash||'#home').slice(1);
 const [page,query='']=raw.split('?');
 if(page!=='noticeview'){show(page);return;}
 const post=new URLSearchParams(query).get('post');
 // Named IDs survive list reordering; accept URLs from the earlier v122 preview too.
 let i=SITE.notices.findIndex(n=>n.id===post);
 if(i<0&&post!==null&&/^(0|[1-9]\d*)$/.test(post))i=Number(post);
 if(Number.isSafeInteger(i)&&i>=0&&SITE.notices[i]){openNotice(i,false);return;}
 show('noticeview');
 document.getElementById('nvTitle').textContent='게시글을 찾을 수 없습니다.';
 document.getElementById('nvBody').textContent='게시글 주소가 올바르지 않거나 삭제된 글입니다. 목록에서 다시 선택해 주세요.';
 ['nvInfo','nvCta','nvNav','nvDate','nvCat'].forEach(id=>document.getElementById(id).textContent='');
 document.getElementById('nvHead').textContent='소식';
 document.getElementById('nvCrumb').textContent='HOME / 소식';
 document.querySelector('#p-noticeview .afoot button').dataset.r='notice';
}
window.addEventListener('popstate',restoreRoute);
window.addEventListener('hashchange',restoreRoute);
function today(){const d=new Date();return d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0');}
function fv(id){const el=document.getElementById(id);return el?el.value:'';}
document.addEventListener('input',e=>{if(['qMember','fType','fStatus','fSrc'].includes(e.target.id))renderMembers();});
document.addEventListener('change',e=>{if(['fType','fStatus','fSrc'].includes(e.target.id))renderMembers();});
renderAuth();renderPublic();featRender();ftimer=setInterval(featNext,5000);
restoreRoute();
// 공지사항·보도자료·자료실은 관리자 콘솔(#admin)에서만 DB 를 읽던 구조였습니다.
// 익명 방문자도 볼 수 있는 테이블이고 RLS SELECT 이 허용되므로, 진입 시 한 번 읽어
// 화면을 갱신합니다. restoreRoute() 뒤에 두는 이유: noticeview 직접 진입 시
// fetchPublicContent() 안에서 목록이 준비된 뒤 다시 해석하도록 되어 있습니다.
fetchPublicContent();
// ForgeDB 세션이 남아 있으면(새로고침·새 탭) 로그인 상태를 그대로 복원합니다.
restoreAuthSession();

// React 마운트 페이지(/#admin AdminLoginCard, /#login LoginPage) 가 호출하는
// 전역 핸들러를 window 에 노출합니다. doLogin 만 React 측에서 참조합니다.
window.doLogin = doLogin;


// Links remain compatible with the original prototype router and keyboard navigation.
document.querySelectorAll('#p-home a[data-r]').forEach(a => a.href = '#' + a.dataset.r);
document.querySelectorAll('#p-home a[data-r]').forEach(a => a.addEventListener('click', e => { e.preventDefault(); const r=a.dataset.r; setRoute(r); show(r); }));
document.querySelectorAll('#p-home .tier[data-r]').forEach(row=>{row.tabIndex=0;row.setAttribute('role','link');row.addEventListener('keydown',e=>{if(e.key==='Enter'){setRoute(row.dataset.r);show(row.dataset.r);}});});


// ─── 라우팅 보강: 모든 페이지의 data-r 링크 / 버튼 ─────────────────────────────
// 기존 코드는 #p-home a[data-r] 만 잡고 있어, 로그인 카드·admin 카드·헤더의
// data-r 링크가 클릭되어도 라우팅되지 않는 문제가 있었음. 모든 페이지에
// 같은 핸들러를 일괄 적용하고 React 컴포넌트가 의존하는 전역(window)을
// 명시적으로 노출하여 폼 submit → doLogin 호출이 정상 동작하도록 보장.
window.doLogin = window.doLogin || doLogin;
window.doSignup = window.doSignup || doSignup;
window.doLogout = window.doLogout || doLogout;
window.setRoute = window.setRoute || setRoute;
window.show = window.show || show;
['p-login','p-admin','p-signup','p-join','p-home'].forEach(function(pid){
  var root = document.getElementById(pid);
  if (!root) return;
  root.querySelectorAll('a[data-r], button[data-r]').forEach(function(el){
    var r = el.dataset.r;
    if (!r) return;
    if (el.tagName === 'A') el.setAttribute('href', '#' + r);
    el.addEventListener('click', function(e){ e.preventDefault(); setRoute(r); show(r); });
  });
});
